function drawCurve(canvas,result){if(!canvas)return;const box=canvas.getBoundingClientRect();if(!box.width)return;const w=box.width,h=155,dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=h*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const extent=Math.max(4.5,Math.min(9,Math.abs(result.t)+.8)),X=x=>22+(x+extent)/(2*extent)*(w-38),Y=p=>h-26-p*(h-48)/.42,baseline=Y(0),inTail=x=>result.alternative==='greater'?x>=result.t:result.alternative==='less'?x<=result.t:Math.abs(x)>=Math.abs(result.t);c.strokeStyle='#c1ccb1';c.beginPath();c.moveTo(X(-extent),baseline);c.lineTo(X(extent),baseline);c.stroke();for(let i=0;i<240;i++){const x=-extent+2*extent*i/240,dx=2*extent/240;if(inTail(x)){c.fillStyle='#c7a36788';c.fillRect(X(x),Y(StudentTMath.pdf(x,result.df)),X(x+dx)-X(x)+.5,baseline-Y(StudentTMath.pdf(x,result.df)));}}c.beginPath();for(let i=0;i<=240;i++){const x=-extent+i/240*extent*2,y=Y(StudentTMath.pdf(x,result.df));i?c.lineTo(X(x),y):c.moveTo(X(x),y);}c.strokeStyle='#ad8c50';c.lineWidth=1.8;c.stroke();c.font='10px Georgia,serif';c.fillStyle='#8a9879';c.textAlign='center';for(const v of [-4,-2,0,2,4])if(Math.abs(v)<=extent)c.fillText(String(v),X(v),h-9);const marker=Math.max(-extent+.1,Math.min(extent-.1,result.t));c.strokeStyle='#81976a';c.setLineDash([3,4]);c.beginPath();c.moveTo(X(marker),baseline);c.lineTo(X(marker),17);c.stroke();c.setLineDash([]);c.textAlign=marker>extent*.5?'right':marker<-extent*.5?'left':'center';c.fillStyle='#8c7546';c.fillText('t='+fmt(result.t)+(Math.abs(result.t)>extent?'（视窗外）':''),X(marker),12);}
function statsResult(result,full=true){const wrap=node('div'),grid=node('div',null,'stats-grid');for(const[label,value]of [['平均值 x̄',fmt(result.mean)],['样本标准差 s',fmt(result.s)],['样本标准误差',fmt(result.se)],['t 值',fmt(result.t)],['自由度 df',String(result.df)],['p 值',pct(result.p)]]){const cell=node('div',null,'stat-cell');cell.append(node('small',label),node('b',value));grid.append(cell);}wrap.append(grid);const canvas=node('canvas',null,'trial-curve');canvas.trialResult=result;if(full)canvas.id='local-trial-curve';canvas.setAttribute('aria-label','t分布及本次结果的尾部区域');wrap.append(canvas);const side={greater:'偏高',less:'偏低','two-sided':'不同'}[result.alternative],conclusion=node('div',null,'trial-conclusion');conclusion.append(node('b',result.significant?'相较基准，结果显著'+side:'尚未发现显著'+side+'的证据'),node('span','p '+(result.significant?'＜':'≥')+' α＝'+result.alpha),node('small','(x̄ − '+result.baseline+') / (s/√n)＝'+fmt(result.t)));wrap.append(conclusion);const interval=result.confidenceInterval;wrap.append(node('p',Math.round(interval.level*100)+'%双侧置信区间：['+fmt(interval.lower)+'，'+fmt(interval.upper)+']','trial-interval'));if(full){const details=node('details',null,'field-note');details.append(node('summary','本次判断的适用条件'),node('p',result.assumptions.join('；')+'。'+result.scope));wrap.append(details);const actions=node('div',null,'result-actions');actions.append(button('请助教解释这次结果',()=>prefill('独立重复数据为'+result.values.join('、')+'，固定基准'+result.baseline+'，事先约定'+{greater:'右尾偏高',less:'左尾偏低','two-sided':'双侧差异'}[result.alternative]+'，α='+result.alpha+'。请核算并解释样本标准误差与尾部概率。','trial-story'),'text-button'),button('练习相同知识点',()=>{selectPractice('trial-story');setView('practice');},'text-button'));wrap.append(actions);}requestAnimationFrame(()=>drawCurve(canvas,result));return wrap;}
function clearAnalysis(){if(state.result){state.result=null;const empty=node('div',null,'empty-result');empty.append(node('span','∿'),node('p','数据或检验条件已修改，请重新计算。'));$('analysis-result').replaceChildren(empty);}$('analysis-error').textContent='';}
