// Render a small Markdown subset with DOM nodes; model output never becomes HTML.
function appendInline(parent,text){
 const tokens=/(`[^`\n]+`|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\([^\s)]+\))/g;let at=0;
 for(const m of text.matchAll(tokens)){
  parent.append(document.createTextNode(text.slice(at,m.index)));const value=m[0];
  if(value.startsWith('`'))parent.append(node('code',value.slice(1,-1)));
  else if(value.startsWith('**'))parent.append(node('strong',value.slice(2,-2)));
  else{const parts=/^\[([^\]]+)\]\(([^)]+)\)$/.exec(value);let url;try{url=new URL(parts[2]);}catch{}
   if(url&&['https:','http:'].includes(url.protocol)&&!url.username&&!url.password&&text[m.index-1]!=='!'){const link=node('a',parts[1]);link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';parent.append(link);}else parent.append(document.createTextNode(value));
  }at=m.index+value.length;
 }parent.append(document.createTextNode(text.slice(at)));
}
function appendText(parent,text){
 const lines=String(text).replace(/\r\n?/g,'\n').split('\n');let list=null,paragraph=null,code=null;
 for(const line of lines){
  if(/^\s*```/.test(line)){if(code)code=null;else{const pre=node('pre');code=node('code');pre.append(code);parent.append(pre);}list=paragraph=null;continue;}
  if(code){code.append(document.createTextNode(line+'\n'));continue;}
  if(!line.trim()){list=paragraph=null;continue;}
  const heading=/^#{1,6}\s+(.+)$/.exec(line),item=/^\s*(?:([-*+])|\d+[.)、])\s+(.+)$/.exec(line);
  if(heading){const h=node('h3');appendInline(h,heading[1]);parent.append(h);list=paragraph=null;}
  else if(item){const kind=item[1]?'ul':'ol';if(!list||list.localName!==kind){list=node(kind);parent.append(list);}const li=node('li');appendInline(li,item[2]);list.append(li);paragraph=null;}
  else{list=null;if(!paragraph){paragraph=node('p');parent.append(paragraph);}else paragraph.append(node('br'));appendInline(paragraph,line);}
 }
}
