function renderMessage(m){const turn=node('div',null,'chat-turn '+m.role);if(m.role==='user'){turn.append(node('p',m.content));return turn;}const body=node('div',null,'assistant-body');body.append(node('small','植知 / DeepSeek'));if(Array.isArray(m.trace)){const traces=node('div',null,'tool-trace');for(const t of m.trace.slice(0,10))if(typeof t.label==='string')traces.append(node('span',(t.success?'✓ ':'')+t.label));body.append(traces);}appendText(body,m.content);const links=node('div',null,'chat-sources');for(const id of (m.sourceIds||[])){const r=D.resource(id);if(r)links.append(openLink(r,r.title+' ↗'));}if(links.childNodes.length)body.append(links);for(const input of (m.calcInputs||[]).slice(0,2)){try{body.append(statsResult(D.trial(input),false));}catch{}}for(const id of (m.practiceIds||[]).slice(0,1)){if(D.resource(id))body.append(practiceUI(D.practice(id),true));}body.append(button('复制回答',()=>copyAnswer(m.content),'text-button copy-answer'));turn.append(body);return turn;}
